def hook(ctx, nb):
    task = ctx.get('task') or {}
    world = ctx.get('world') or {}
    adm = [str(a) for a in ctx.get('admissible') or []]
    actd = ctx.get('action') or {}
    a = ''
    if isinstance(actd, dict):
        a = str(actd.get('final_action') or actd.get('normalized') or actd.get('raw') or '')
    if not a:
        a = str(ctx.get('action.final_action') or ctx.get('action.normalized') or ctx.get('action.raw') or '')
    ttype = str(task.get('task_type') or ctx.get('task.task_type') or '')
    target = str(task.get('target_type') or ctx.get('task.target_type') or '')
    dest = str(task.get('destination_type') or ctx.get('task.destination_type') or '')
    verb = ''
    place = ''
    if 'clean' in ttype:
        verb = 'clean'
        place = 'sinkbasin'
    if 'heat' in ttype:
        verb = 'heat'
        place = 'microwave'
    if 'cool' in ttype:
        verb = 'cool'
        place = 'fridge'
    inv = world.get('inventory') or ''
    carrying = bool(target and target in inv and 'not carrying' not in inv)
    wrong = bool(inv and not carrying)
    found = bool(world.get('target_found'))
    loc = str(world.get('target_location') or '')
    transact = ''
    putact = ''
    takeact = ''
    if verb:
        for x in adm:
            if x.startswith(verb + ' ') and target in x:
                transact = x
    for x in adm:
        if x.startswith('put ') and target in x and dest in x:
            putact = x
        if x.startswith('take ') and target in x and loc and loc in x:
            takeact = x
    nb['required_verb'] = verb
    nb['transform_place'] = place
    if wrong:
        stage = 'wrong_inventory'
    else:
        if carrying:
            if verb:
                if nb.get('transform_done'):
                    stage = 'put_target'
                else:
                    stage = 'transform'
            else:
                stage = 'put_target'
        else:
            if found or takeact:
                stage = 'take_target'
            else:
                stage = 'find_target'
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    task = ctx.get('task') or {}
    ttype = str(task.get('task_type') or ctx.get('task.task_type') or '')
    target = str(task.get('target_type') or ctx.get('task.target_type') or 'target object')
    dest = str(task.get('destination_type') or ctx.get('task.destination_type') or 'destination')
    stage = nb.get('stage')
    verb = str(nb.get('required_verb') or '')
    place = str(nb.get('transform_place') or '')
    msg = ''
    if stage == 'take_target':
        msg = 'A matching ' + target + ' is visible here. Take it now with the available take action instead of searching more places.'
    elif stage == 'transform':
        msg = 'You are carrying the ' + target + '. Go to a ' + place + ' and use the available ' + verb + ' action with it. Do not put it down yet.'
    elif stage == 'put_target':
        msg = 'You are at or near a ' + dest + '. Use the available put action for the ' + target + ' in/on the ' + dest + ' to finish this part of the task.'
    elif stage == 'find_target':
        if 'two' in ttype:
            msg = 'Search visible surfaces for another ' + target + ' that is not already at the ' + dest + '. Do not take back an item you have already placed.'
        else:
            msg = 'Search visible surfaces or open containers for a ' + target + '. Take it as soon as its take action appears in AVAILABLE ACTIONS.'
    elif stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested target. Do not force a destination put; recover by setting aside the wrong item if possible and searching for a ' + target + '.'
    if not msg:
        return None
    key = stage + ':' + msg
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}
